CREATE VIEW VUE_TRSRECABS AS   SELECT     dbo.Vue_TrsRec.TrsType, dbo.Vue_TrsRec.Coycode, dbo.Vue_TrsRec.DcNo,dbo.Vue_TrsRec.clos, dbo.Vue_TrsRec.DcFinyear, dbo.Vue_TrsRec.GrnNo, dbo.Vue_TrsRec.Finyear, dbo.Vue_TrsRec.GrnDate,  dbo.Vue_TrsRec.ordid, dbo.Vue_TrsRec.Pname, dbo.Vue_TrsRec.PID, dbo.Vue_TrsRec.PartyDCref, dbo.Vue_TrsRec.Deptname, dbo.Vue_TrsRec.DeptID, dbo.StockTable.YF,  dbo.Mas_Count.CountName, dbo.Mas_Color.ColorDesc, dbo.Mas_Mill.ShortMill, dbo.Mas_Fabric.Fabdesc, SUM(dbo.Vue_TrsRec.RBag) 
AS RBag, SUM(dbo.Vue_TrsRec.RecKgs) AS RecKgs, SUM(dbo.Vue_TrsRec.Recmtr) AS Recmtr, dbo.Mas_Uom.Uom, dbo.Mas_Acc.Acc_Descr, dbo.Mas_AccDes.AccDescription, AccUom.Uom AS Expr1, dbo.Vue_TrsRec.ProcessType, Mas_Design.DesignDesc,MultiGRN,IsNull(SubProcess,'') as SubProcess FROM Mas_Count RIGHT OUTER JOIN Mas_Uom RIGHT OUTER JOIN Mas_Fabric ON Mas_Uom.UomID = Mas_Fabric.PriUomID RIGHT OUTER JOIN Mas_Acc RIGHT OUTER JOIN Mas_Design RIGHT OUTER JOIN Vue_TrsRec INNER JOIN StockTable ON Vue_TrsRec.StockID = StockTable.StockID ON Mas_Design.DesignId = StockTable.PRINT_DESIGNID ON  Mas_Acc.ID = StockTable.Atype LEFT OUTER  JOIN Mas_AccDes ON Mas_Acc.ID = Mas_AccDes.AccTypeID AND StockTable.Ades = Mas_AccDes.ID LEFT OUTER JOIN Mas_Uom AS AccUom ON Mas_Acc.UomId = AccUom.UomID ON Mas_Fabric.FabID = StockTable.FabID LEFT OUTER JOIN Mas_Color ON StockTable.ColID = Mas_Color.ColID ON Mas_Count.CountID = StockTable.CntID LEFT OUTER JOIN Mas_Mill ON StockTable.MillID = Mas_Mill.MillID LEFT JOIN Mas_SubProcess ON Vue_TrsRec.SubPrsID = Mas_SubProcess.ID GROUP BY Vue_TrsRec.TrsType, Vue_TrsRec.Coycode, Vue_TrsRec.DcNo,Vue_TrsRec.clos, Vue_TrsRec.DcFinyear, Vue_TrsRec.GrnNo, Vue_TrsRec.Finyear, Vue_TrsRec.GrnDate,Vue_TrsRec.ordid, Vue_TrsRec.Pname, Vue_TrsRec.PID, Vue_TrsRec.PartyDCref, Vue_TrsRec.Deptname, Vue_TrsRec.DeptID, StockTable.YF,StockTable.CntID,StockTable.ColID, Mas_Count.CountName, Mas_Color.ColorDesc, Mas_Mill.ShortMill, Mas_Fabric.Fabdesc, Mas_Uom.Uom, Mas_Acc.Acc_Descr, Mas_AccDes.AccDescription, AccUom.Uom, Vue_TrsRec.ProcessType, Mas_Design.DesignDesc,MultiGRN,IsNull(SubProcess,'')
